const zlib = require("zlib");
const crypto = require("crypto");
let pageCached = null;
function pageVariant() {
  if (!pageCached) {
    const raw = Buffer.from(PAGE, "utf8");
    pageCached = { raw: raw, br: null, gz: null, etag: '"' + crypto.createHash("sha1").update(raw).digest("hex").slice(0, 24) + '"' };
  }
  return pageCached;
}

module.exports = async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  try {
    const q = req.query || {};
    const slug = String(q.b || "");

    // Promemoria per Calendario di iPhone/iPad: file .ics con avviso 1 ora prima.
    if (req.method === "GET" && q.ics === "1") {
      const s0 = Date.parse(String(q.s || "")), e0 = Date.parse(String(q.e || ""));
      const okDate = (n) => Number.isFinite(n) && n > Date.UTC(2020, 0, 1) && n < Date.UTC(2100, 0, 1);
      if (!okDate(s0) || !okDate(e0) || e0 <= s0 || e0 - s0 > 12 * 3600 * 1000) return res.status(400).json({ error: "Richiesta non valida" });
      const esc = (x, n) => String(x || "").slice(0, n).replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
      const fmt = (ms) => new Date(ms).toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
      const ics = [
        "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//LIA//Appuntamento//IT", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
        "BEGIN:VEVENT",
        "UID:" + s0 + "-" + Math.abs(esc(q.t, 120).length * 7919 + e0) + "@lia",
        "DTSTAMP:" + fmt(Date.now()), "DTSTART:" + fmt(s0), "DTEND:" + fmt(e0),
        "SUMMARY:" + esc(q.t || "Appuntamento", 120),
        "DESCRIPTION:" + esc(q.d, 300),
        "LOCATION:" + esc(q.l, 200),
        "BEGIN:VALARM", "TRIGGER:-PT60M", "ACTION:DISPLAY", "DESCRIPTION:Promemoria appuntamento", "END:VALARM",
        "END:VEVENT", "END:VCALENDAR",
      ].join("\r\n") + "\r\n";
      res.setHeader("Content-Type", "text/calendar; charset=utf-8");
      res.setHeader("Content-Disposition", 'inline; filename="appuntamento.ics"');
      return res.status(200).send(ics);
    }

    const wantsData = req.method === "POST" || q.info === "1" || !!q.date || !!q.month || !!q.cancel;
    if (req.method === "GET" && !wantsData) {
      res.setHeader("Content-Type", "text/html; charset=utf-8");
      // Pagina uguale per tutti: compressa una volta sola e con ETag, cosi' ai clienti arriva piu' leggera e alle visite successive basta un "304".
      const pv = pageVariant();
      res.setHeader("Cache-Control", "public, max-age=0, must-revalidate");
      res.setHeader("ETag", pv.etag);
      res.setHeader("Vary", "Accept-Encoding");
      if (String(req.headers["if-none-match"] || "") === pv.etag) { res.statusCode = 304; return res.end(); }
      const ae = String(req.headers["accept-encoding"] || "");
      let body = pv.raw;
      try {
        if (/\bbr\b/.test(ae)) {
          if (!pv.br) pv.br = zlib.brotliCompressSync(pv.raw, { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 5, [zlib.constants.BROTLI_PARAM_SIZE_HINT]: pv.raw.length } });
          body = pv.br; res.setHeader("Content-Encoding", "br");
        } else if (/\bgzip\b/.test(ae)) {
          if (!pv.gz) pv.gz = zlib.gzipSync(pv.raw, { level: 6 });
          body = pv.gz; res.setHeader("Content-Encoding", "gzip");
        }
      } catch (e) { body = pv.raw; res.removeHeader("Content-Encoding"); }
      res.setHeader("Content-Length", body.length);
      res.statusCode = 200;
      return res.end(body);
    }

    if (!/^[a-z0-9-]{1,60}$/.test(slug)) return res.status(404).json({ error: "Attività non trovata" });
    const biz = await getBusiness(slug);
    if (!biz) return res.status(404).json({ error: "Attività non trovata" });

    // Pagina di annullamento aperta dal link dell'email.
    if (req.method === "GET" && q.cancel) {
      const cid = String(q.cancel || "");
      const base = { slug, bizName: biz.name, phone: biz.public_phone || "", tz: biz.timezone, id: cid, k: String(q.k || "") };
      res.setHeader("Content-Type", "text/html; charset=utf-8");
      res.setHeader("Cache-Control", "no-store");
      if (!/^[0-9a-zA-Z-]{1,64}$/.test(cid) || !mail.validCancelSig(cid, String(q.k || ""))) return res.status(200).send(cancelPageHtml({ ...base, state: "gone" }));
      const ar = await sb("GET", "appointments?id=eq." + encodeURIComponent(cid) + "&business_id=eq." + biz.id + "&select=status,starts_at,ends_at,services(name),resources(name)");
      const ap = ar.ok && Array.isArray(ar.data) ? ar.data[0] : null;
      if (!ap || ap.status !== "confirmed") return res.status(200).send(cancelPageHtml({ ...base, state: "gone" }));
      const det = { start: new Date(ap.starts_at), service: ap.services ? ap.services.name : "", staff: (biz.__teamMode && biz.staff_choice === true && ap.resources) ? ap.resources.name : "" };
      if (det.start.getTime() <= Date.now()) return res.status(200).send(cancelPageHtml({ ...base, ...det, state: "past" }));
      const lim = cancelLimitH(biz);
      if (lim > 0 && det.start.getTime() - Date.now() < lim * 3600000) return res.status(200).send(cancelPageHtml({ ...base, ...det, state: "toolate", limitText: mail.limitText ? mail.limitText(lim) : lim + " ore" }));
      return res.status(200).send(cancelPageHtml({ ...base, ...det, state: "ask" }));
    }

    // Annullamento dalla pagina di conferma o dal link dell'email (serve l'id e il telefono usato, oppure il codice firmato).
    if (req.method === "POST" && q.action === "cancel") {
      const cb = req.body || {};
      const cid = String(cb.id || "");
      const cphone = String(cb.phone || "").trim();
      const viaLink = !!cb.k && mail.validCancelSig(cid, String(cb.k));
      if (!/^[0-9a-zA-Z-]{1,64}$/.test(cid) || (!cphone && !viaLink)) return res.status(400).json({ error: "Richiesta non valida" });
      const who = viaLink ? "" : "&contact_id=eq." + encodeURIComponent(cphone);
      const lim = cancelLimitH(biz);
      if (lim > 0) {
        const cur = await sb("GET", "appointments?id=eq." + encodeURIComponent(cid) + "&business_id=eq." + biz.id + who + "&status=eq.confirmed&select=starts_at");
        const st = cur.ok && Array.isArray(cur.data) && cur.data[0] ? Date.parse(cur.data[0].starts_at) : NaN;
        if (Number.isFinite(st) && st - Date.now() < lim * 3600000) {
          return res.status(409).json({ error: "Non si può più annullare online: mancano meno di " + (lim === 1 ? "1 ora" : lim + " ore") + " all'appuntamento." + (biz.public_phone ? " Chiama il " + biz.public_phone + "." : " Contatta direttamente l'attività."), too_late: true, phone: biz.public_phone || "" });
        }
      }
      const cr = await sb(
        "PATCH",
        "appointments?id=eq." + encodeURIComponent(cid) + "&business_id=eq." + biz.id + who + "&status=eq.confirmed",
        { status: "cancelled" },
        "return=representation"
      );
      if (!cr.ok || !Array.isArray(cr.data) || !cr.data.length) return res.status(404).json({ error: "Appuntamento non trovato o gia' annullato." });
      return res.status(200).json({ ok: true });
    }

    // Abbonamento non rinnovato: niente nuove prenotazioni online.
    const acc = await getAccess(biz.id);
    if (!acc.allowed) return res.status(503).json({ error: BOOKING_BLOCKED_MESSAGE });

    if (req.method === "GET" && q.info === "1") {
      return res.status(200).json({
        lia_allowed: acc.lia_allowed !== false,
        max_days: MAX_DAYS_AHEAD,
        booking_rules: { min_notice_min: leadMin(biz), cancel_limit_hours: cancelLimitH(biz) },
        team: (biz.__teamMode && biz.staff_choice === true)
          ? { staff: biz.resources.map((r) => ({ id: r.id, name: r.name, service_ids: (biz.__svc && biz.__svc[r.id]) || [] })) }
          : null,
        rules: (() => { const pr = partyRules(biz); return pr ? { players: pr.players, members: pr.members, certificate: pr.certificate, member_daily_min: pr.memberDailyMin } : null; })(),
        name: biz.name,
        type: biz.business_type,
        timezone: biz.timezone,
        address: biz.address || "",
        tagline: biz.public_tagline || "",
        phone: biz.public_phone || "",
        instagram: biz.public_instagram || "",
        facebook: biz.public_facebook || "",
        hours: (() => { const o = [[], [], [], [], [], [], []]; const hr = biz.__hoursResource; ((hr && hr.opening_hours) || []).forEach((h) => { const i = Number(h.weekday) - 1; if (i >= 0 && i < 7) o[i].push({ opens: String(h.opens).slice(0, 5), closes: String(h.closes).slice(0, 5) }); }); o.forEach((a) => a.sort((x, y) => (x.opens < y.opens ? -1 : 1))); return o; })(),
        services: biz.services
          .filter((s) => !isPackage(s) || !biz.__teamMode || eligibleStaff(biz, s).length > 0)
          .map((s) => {
            const o = { id: s.id, name: s.name, duration_min: s.duration_min, price_eur: s.price_eur, at_customer_place: s.at_customer_place };
            if (isPackage(s)) {
              o.package = true;
              o.includes = s.package_service_ids.map((id) => { const x = biz.services.find((y) => y.id === id); return x ? x.name : null; }).filter(Boolean).join(" + ");
              const sum = s.package_service_ids.reduce((a, id) => { const x = biz.services.find((y) => y.id === id); return a + (x ? Number(x.price_eur) || 0 : 0); }, 0);
              if (sum > Number(s.price_eur)) o.full_price_eur = sum;
              o.package_service_ids = s.package_service_ids;
            }
            return o;
          }),
      });
    }

    if (req.method === "GET" && q.month) {
      const service = biz.services.find((s) => s.id === q.service);
      if (!service) return res.status(400).json({ error: "Servizio non valido" });
      if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(String(q.month))) return res.status(400).json({ error: "Mese non valido" });
      const bzm = bizFor(biz, q.staff);
      if (!bzm) return res.status(400).json({ error: "Persona non valida" });
      return res.status(200).json(await monthAvailability(bzm, service, String(q.month)));
    }

    if (req.method === "GET" && q.date) {
      const service = biz.services.find((s) => s.id === q.service);
      if (!service) return res.status(400).json({ error: "Servizio non valido" });
      const bad = checkDate(biz, q.date);
      if (bad) return res.status(400).json({ error: bad });
      const bzd = bizFor(biz, q.staff);
      if (!bzd) return res.status(400).json({ error: "Persona non valida" });
      const slots = await freeSlots(bzd, service, q.date);
      const times = Array.from(new Set(slots.map((s) => s.time))).sort();
      return res.status(200).json({ times: times });
    }

    if (req.method === "POST") {
      const body = req.body || {};
      const service = biz.services.find((s) => s.id === body.service);
      if (!service) return res.status(400).json({ error: "Servizio non valido" });
      const bad = checkDate(biz, body.date);
      if (bad) return res.status(400).json({ error: bad });
      if (!/^\d{2}:\d{2}$/.test(String(body.time || ""))) return res.status(400).json({ error: "Orario non valido" });
      const name = String(body.name || "").trim();
      const phone = String(body.phone || "").trim();
      if (name.length < 2) return res.status(400).json({ error: "Nome mancante" });
      const phoneErr = phoneProblem(phone);
      if (phoneErr) return res.status(400).json({ error: phoneErr });
      const emailErr = emailProblem(body.email);
      if (emailErr) return res.status(400).json({ error: emailErr });
      const email = mail.normalizeEmail(body.email);
      if (service.at_customer_place && !String(body.address || "").trim()) {
        return res.status(400).json({ error: "Indirizzo mancante" });
      }

      const rules = partyRules(biz);
      let party = null;
      if (rules) {
        party = validateParty(rules, body);
        if (party.error) return res.status(400).json({ error: party.error });
        const lim = await memberDayCheck(biz, rules, party, phone, body.date, service.duration_min, String(body.replace || "") || null);
        if (lim) return res.status(400).json({ error: lim });
      }

      // Anti-abuso: campo nascosto compilato solo dai robot, tetto agli appuntamenti futuri per numero
      // e alle prenotazioni online all'ora. Se un controllo non riesce, si lascia passare.
      if (String(body.website || "").trim()) return res.status(400).json({ error: "Richiesta non valida" });
      try {
        const nowIso = encodeURIComponent(new Date().toISOString());
        const mine = await sb("GET", "appointments?business_id=eq." + biz.id + "&contact_id=eq." + encodeURIComponent(phone) + "&status=eq.confirmed&starts_at=gt." + nowIso + "&select=id&limit=" + (MAX_ACTIVE_PER_PHONE + 1));
        if (mine.ok && Array.isArray(mine.data) && mine.data.length >= MAX_ACTIVE_PER_PHONE) {
          return res.status(429).json({ error: "Hai gia' " + MAX_ACTIVE_PER_PHONE + " appuntamenti in programma. Annullane uno prima di prenotarne un altro." });
        }
        const hourAgo = encodeURIComponent(new Date(Date.now() - 3600000).toISOString());
        const flood = await sb("GET", "appointments?business_id=eq." + biz.id + "&channel=eq.selfservice&created_at=gt." + hourAgo + "&select=id&limit=" + (MAX_SELF_PER_HOUR + 1));
        if (flood.ok && Array.isArray(flood.data) && flood.data.length > MAX_SELF_PER_HOUR) {
          return res.status(429).json({ error: "Troppe prenotazioni in poco tempo. Riprova tra qualche minuto." });
        }
      } catch (e) { console.error("Controllo limiti non riuscito (ignoro):", e && e.message); }

      const bzp = bizFor(biz, body.staff);
      if (!bzp) return res.status(400).json({ error: "Persona non valida" });
      const slots = await freeSlots(bzp, service, body.date);
      const candidates = slots.filter((s) => s.time === body.time);
      if (!candidates.length) return res.status(409).json({ error: "Questo orario non è più disponibile. Aggiorna la pagina e scegline un altro." });

      const start = zonedTimeToUtc(body.date, body.time, biz.timezone);
      const end = new Date(start.getTime() + service.duration_min * 60000);
      const blocked = new Date(end.getTime() + (service.buffer_min || 0) * 60000);

      for (const c of candidates) {
        const apRow = {
          business_id: biz.id,
          resource_id: c.resource_id,
          service_id: service.id,
          customer_name: name,
          customer_phone: phone,
          customer_address: body.address || null,
          starts_at: start.toISOString(),
          ends_at: end.toISOString(),
          blocked_until: blocked.toISOString(),
          channel: "selfservice",
          contact_id: phone,
          ...(email ? { customer_email: email } : {}),
          ...(party ? { players: party.players, members: party.members } : {}),
          ...(["qr", "vetrina"].includes(String(body.src || "")) ? { source: String(body.src) } : {}), // QR del link (qr) o QR della locandina in vetrina (vetrina)
        };
        let r = await sb("POST", "appointments", apRow, "return=representation");
        if (!r.ok && r.status === 400 && (apRow.source || apRow.customer_email)) { delete apRow.source; delete apRow.customer_email; r = await sb("POST", "appointments", apRow, "return=representation"); } // colonna source o customer_email non ancora creata: salva comunque la prenotazione
        if (r.ok) {
          // Avviso sul telefono del titolare (se ha attivato le notifiche). Non blocca mai la prenotazione.
          await require("../lib/push.js").notifyNewBooking(biz.id, { name: name, service: service.name, startsAt: start.toISOString(), timezone: biz.timezone });
          // Email di conferma (solo se il cliente ha lasciato l'indirizzo). Non blocca mai la prenotazione.
          let emailSent = false;
          const newId = Array.isArray(r.data) && r.data[0] ? r.data[0].id : null;
          if (email && newId) {
            try {
              const em = mail.appointmentEmail({ kind: "confirm", slug, apptId: newId, bizName: biz.name, bizPhone: biz.public_phone || "", bizAddress: biz.address || "", customerName: name, service: service.name, staffName: (biz.__teamMode && biz.staff_choice === true) ? ((biz.resources.find((x) => x.id === c.resource_id) || {}).name || "") : "", startsAt: start.toISOString(), endsAt: end.toISOString(), tz: biz.timezone, customerAddress: service.at_customer_place ? String(body.address || "") : "", cancelLimitH: cancelLimitH(biz), privacyUrl: mail.baseUrl() + "/privacy/" + slug });
              emailSent = await Promise.race([mail.sendMail(email, em.subject, em.html, em.text, biz.name), new Promise((ok) => setTimeout(() => ok(false), 4500))]);
            } catch (e) { console.error("Email di conferma non inviata:", e && e.message); }
          }
          return res.status(200).json({ ok: true, email_sent: !!emailSent, staff_name: (biz.__teamMode && biz.staff_choice === true) ? ((biz.resources.find((x) => x.id === c.resource_id) || {}).name || null) : null, ...(party ? { players: party.players, members: party.members, due_eur: party.nonMembers * Number(service.price_eur || 0) } : {}), id: (Array.isArray(r.data) && r.data[0] ? r.data[0].id : null), calendar: { title: service.name + " - " + biz.name, start: start.toISOString(), end: end.toISOString(), location: service.at_customer_place ? String(body.address || "") : String(biz.address || ""), description: "Appuntamento confermato con " + biz.name } });
        }
        if (r.status !== 409) { console.error("Errore prenotazione:", r.status, r.data); return res.status(500).json({ error: "Errore nel salvataggio" }); }
      }
      return res.status(409).json({ error: "Questo orario è appena stato preso. Aggiorna la pagina e scegline un altro." });
    }

    return res.status(405).json({ error: "Metodo non permesso" });
  } catch (e) {
    console.error(e);
    return res.status(500).json({ error: "Errore" });
  }
};
